 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let position = 0;
+  while (position < template.length) {
+    const open = template.indexOf("{{", position);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(position) });
+      break;
+    }
+    if (open > position) {
+      tokens.push({ kind: "text", text: template.slice(position, open) });
+    }
+    const raw = template.startsWith("{{{", open);
+    const delimiter = raw ? "}}}" : "}}";
+    const contentStart = open + (raw ? 3 : 2);
+    const close = template.indexOf(delimiter, contentStart);
+    if (close === -1) {
+      throw new Error("unterminated tag");
+    }
+    tokens.push(tagToken(template.slice(contentStart, close).trim(), raw));
+    position = close + delimiter.length;
+  }
+  return tokens;
 }
+
+function tagToken(content: string, raw: boolean): Token {
+  if (raw) {
+    return { kind: "value", expr: content, raw: true };
+  }
+  if (content === "else") {
+    return { kind: "else" };
+  }
+  if (content === "/if") {
+    return { kind: "end" };
+  }
+  if (/^#if(\s|$)/.test(content)) {
+    return { kind: "if", path: content.slice(3).trim() };
+  }
+  return { kind: "value", expr: content, raw: false };
+}
